#include "autonicer.h"
#include "config.h"
#include "registry.h"
#include "controller.h"
#include "logger.h"
#include "monitor.h"
#include "process.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/resource.h>
#include <signal.h>
#include <errno.h>
#include <sys/stat.h>

int parse_pid(const char*s,pid_t*p){char*e;long v=strtol(s,&e,10);if(*s==0||*e||v<1||v>2147483647)return -1;*p=(pid_t)v;return 0;}
static void help(void){puts("autonicer monitor [--dry-run]\nautonicer list|status|history|config\nautonicer classify PID normal|background|critical\nautonicer protect|unprotect PID\nautonicer restore|resume PID");}
int main(int argc,char**argv){const char*home=getenv("HOME");if(!home)home=".";AutoNicerConfig c;ManagedProcess*a=NULL;size_t n=0;char dir[256],state[320],log[320],cfgpath[320];snprintf(dir,sizeof dir,"%s/.local/state/autonicer",home);snprintf(state,sizeof state,"%s/registry",dir);snprintf(log,sizeof log,"%s/history",dir);snprintf(cfgpath,sizeof cfgpath,"%s/config",dir);char parent[256];snprintf(parent,sizeof parent,"%s/.local",home);mkdir(parent,0700);snprintf(parent,sizeof parent,"%s/.local/state",home);mkdir(parent,0700);mkdir(dir,0700);config_defaults(&c);config_load(&c,cfgpath);registry_load(&a,&n,state);if(argc<2){help();free(a);return 0;}if(!strcmp(argv[1],"help")){help();free(a);return 0;}if(!strcmp(argv[1],"sample")){SystemSample x,y;if(monitor_read(&x)){free(a);return 1;}sleep(c.sample_interval);if(monitor_sample(&x,&y)){free(a);return 1;}printf("{\"cpuPercent\":%.1f,\"loadState\":\"%s\",\"timestamp\":%ld}\n",y.utilization,y.utilization>=c.critical_threshold?"CRITICAL":y.utilization>=c.high_threshold?"HIGH":"NORMAL",(long)y.timestamp.tv_sec);free(a);return 0;}if(!strcmp(argv[1],"monitor")){int dry=argc>2&&!strcmp(argv[2],"--dry-run");int r=controller_monitor(&c,a,n,dry,log);registry_save(a,n,state);free(a);return r?1:0;}if(!strcmp(argv[1],"list")||!strcmp(argv[1],"status")){int json=argc>2&&!strcmp(argv[2],"--json");if(json)puts("[");for(size_t i=0;i<n;i++){ProcessInfo p;if(process_read(a[i].info.pid,&p)==0)a[i].info=p;if(json)printf("%s{\"pid\":%d,\"name\":\"%s\",\"cpuPercent\":%.1f,\"nice\":%d,\"state\":\"%c\",\"classification\":\"%s\",\"protected\":%s,\"priorityChanged\":%s,\"paused\":%s}\n",i?",":"",a[i].info.pid,a[i].info.name,a[i].info.recent_cpu_percent,a[i].info.nice_value,a[i].info.state,class_name(a[i].classification),a[i].protected_flag?"true":"false",a[i].priority_changed?"true":"false",a[i].paused_by_autonicer?"true":"false");else printf("%d | %s | nice=%d | %s | %s\n",a[i].info.pid,a[i].info.name,a[i].last_nice,class_name(a[i].classification),a[i].protected_flag?"PROTECTED":"-");}if(json)puts("]");free(a);return 0;}if(!strcmp(argv[1],"history")){int r=logger_print(log);free(a);return r?1:0;}if(!strcmp(argv[1],"config")){config_print(&c);free(a);return 0;}pid_t pid;if(argc<3||parse_pid(argv[2],&pid)){help();free(a);return 1;}int r=0;if(!strcmp(argv[1],"classify")&&argc>=4){ProcessClass cl;if(!strcmp(argv[3],"background"))cl=PROCESS_BACKGROUND;else if(!strcmp(argv[3],"critical"))cl=PROCESS_CRITICAL;else if(!strcmp(argv[3],"normal"))cl=PROCESS_NORMAL;else r=-1;if(!r)r=registry_classify(&a,&n,pid,cl,getuid());}else if(!strcmp(argv[1],"protect")||!strcmp(argv[1],"unprotect"))r=registry_protect(a,n,pid,!strcmp(argv[1],"protect"));else if(!strcmp(argv[1],"restore")){ManagedProcess*m=registry_find(a,n,pid);if(!m||!m->priority_changed)r=-1;else if(setpriority(PRIO_PROCESS,pid,m->original_nice)){fprintf(stderr,"Restore failed: %s\n",strerror(errno));r=-1;}else{m->last_nice=m->original_nice;puts("Priority restored.");}}else if(!strcmp(argv[1],"resume")){ManagedProcess*m=registry_find(a,n,pid);if(!m||!m->paused_by_autonicer||kill(pid,SIGCONT)){r=-1;puts("Resume failed or process was not paused by AutoNicer.");}else{m->paused_by_autonicer=0;puts("Process resumed.");}}else r=-1;if(r)fprintf(stderr,"Operation failed safely.\n");registry_cleanup(a,&n);registry_save(a,n,state);free(a);return r?1:0;}
